const getLogoText = (name: string): string => {
  if (name.startsWith('BNP')) return 'BNP';
  if (name.startsWith('MG')) return 'MG';
  
  const coreName = name
    .replace(/(손해보험|연금보험|라이프생명|손해|화재|생명|보험|연금|해상|라이프)/g, '')
    .trim();

  if (coreName.length >= 3) {
    return coreName.substring(0, 3);
  }
  return coreName;
};

