const normalizeString = (str: any) => {
  if (str === null || str === undefined) return '';
  return String(str).replace(/[^a-zA-Z0-9가-힣ㄱ-ㅎㅏ-ㅣ]/g, '').toLowerCase();
};

const escapeRegExp = (string: string) => {
  if (!string) return '';
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
};




